import{_ as e,o as i,c as l,O as t}from"./chunks/framework.db831a78.js";const P=JSON.parse('{"title":"分布式 & 高并发","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/08-分布式高并发.md","filePath":"interview/后端/Java/08-分布式高并发.md","lastUpdated":null}'),r={name:"interview/后端/Java/08-分布式高并发.md"};function o(n,a,d,s,c,h){return i(),l("div",null,a[0]||(a[0]=[t('<h1 id="分布式-高并发" tabindex="-1">分布式 &amp; 高并发 <a class="header-anchor" href="#分布式-高并发" aria-label="Permalink to &quot;分布式 &amp; 高并发&quot;">​</a></h1><blockquote><p>常问等级：★★★ 高频必考 / ★★☆ 中频常见 / ★☆☆ 低频了解</p></blockquote><h2 id="cap、base-理论-★★★" tabindex="-1">CAP、BASE 理论 ★★★ <a class="header-anchor" href="#cap、base-理论-★★★" aria-label="Permalink to &quot;CAP、BASE 理论 ★★★&quot;">​</a></h2><ul><li>CAP：一致性 Consistency、可用性 Availability、分区容错 Partition tolerance，三者不可兼得，分布式必须保证 P，故在 C 与 A 间取舍（如 ZooKeeper 偏 CP，Eureka 偏 AP）。</li><li>BASE：基本可用、软状态、最终一致，是对 AP 的实践，牺牲强一致换取可用性。</li></ul><h2 id="分布式事务-2pc、3pc、tcc、saga、本地消息表、可靠消息最终一致性-★★★" tabindex="-1">分布式事务：2PC、3PC、TCC、SAGA、本地消息表、可靠消息最终一致性 ★★★ <a class="header-anchor" href="#分布式事务-2pc、3pc、tcc、saga、本地消息表、可靠消息最终一致性-★★★" aria-label="Permalink to &quot;分布式事务：2PC、3PC、TCC、SAGA、本地消息表、可靠消息最终一致性 ★★★&quot;">​</a></h2><ul><li>2PC：准备/提交两阶段（XA），同步阻塞、协调者单点、部分失败数据不一致；3PC 加超时减少阻塞但不能完全解决。</li><li>TCC：Try-Confirm-Cancel，业务自己实现补偿，强一致、侵入大，适合资金类。</li><li>SAGA：长事务拆有序子事务，正向执行 + 反向补偿。</li><li>本地消息表：本地事务中写业务 + 消息表，后台定时重试投递，最终一致。</li><li>可靠消息最终一致：事务消息（RocketMQ 半消息 + 回查），保证本地事务与消息发送一致。</li></ul><h2 id="分布式-id-生成方案-★★★" tabindex="-1">分布式 ID 生成方案 ★★★ <a class="header-anchor" href="#分布式-id-生成方案-★★★" aria-label="Permalink to &quot;分布式 ID 生成方案 ★★★&quot;">​</a></h2><ul><li>UUID：简单但无序（影响索引写入、占用大）；数据库自增：有序但单点瓶颈、暴露业务量；号段模式（Leaf）：批量取号段；Redis 自增；雪花算法 Snowflake：时间戳 + 机器 id + 序列号，有序高效但依赖时钟（时钟回拨问题）。</li></ul><h2 id="接口幂等性设计-★★★" tabindex="-1">接口幂等性设计 ★★★ <a class="header-anchor" href="#接口幂等性设计-★★★" aria-label="Permalink to &quot;接口幂等性设计 ★★★&quot;">​</a></h2><ul><li>幂等定义：同一请求多次执行结果一致。</li><li>方案：数据库唯一索引、悲观/乐观锁（version）、状态机约束、Token 防重（先取 token 再校验消费）、分布式锁、Redis setnx，配合全局唯一请求号去重。</li></ul><h2 id="限流、熔断、降级-★★★" tabindex="-1">限流、熔断、降级 ★★★ <a class="header-anchor" href="#限流、熔断、降级-★★★" aria-label="Permalink to &quot;限流、熔断、降级 ★★★&quot;">​</a></h2><ul><li>限流：限制请求速率，保护系统；熔断：下游异常率/慢调用达阈值后快速失败（Sentinel/Hystrix 三种状态）；降级：非核心功能关闭/兜底返回。</li></ul><h2 id="限流算法-计数器-滑动窗口-令牌桶-漏桶-★★★" tabindex="-1">限流算法（计数器/滑动窗口/令牌桶/漏桶）★★★ <a class="header-anchor" href="#限流算法-计数器-滑动窗口-令牌桶-漏桶-★★★" aria-label="Permalink to &quot;限流算法（计数器/滑动窗口/令牌桶/漏桶）★★★&quot;">​</a></h2><ul><li>计数器：固定窗口，临界突刺问题；滑动窗口：细分窗口平滑；漏桶：恒定速率流出，平滑但突发受限；令牌桶：匀速放令牌、突发可取，允许瞬时峰值，最常用（Sentinel/Guava RateLimiter）。</li></ul><h2 id="负载均衡算法、一致性哈希-★★★" tabindex="-1">负载均衡算法、一致性哈希 ★★★ <a class="header-anchor" href="#负载均衡算法、一致性哈希-★★★" aria-label="Permalink to &quot;负载均衡算法、一致性哈希 ★★★&quot;">​</a></h2><ul><li>负载均衡：轮询、随机、加权轮询/随机、最少连接、一致性哈希、源地址哈希。</li><li>一致性哈希：环上分配节点，减少节点增减时的数据迁移；引入虚拟节点解决数据倾斜。</li></ul><h2 id="分布式锁方案对比-redis-zk-db-★★★" tabindex="-1">分布式锁方案对比（Redis/ZK/DB）★★★ <a class="header-anchor" href="#分布式锁方案对比-redis-zk-db-★★★" aria-label="Permalink to &quot;分布式锁方案对比（Redis/ZK/DB）★★★&quot;">​</a></h2><ul><li>Redis：性能高，SET NX PX + Lua 释放 + 看门狗续期；有主从切换丢锁风险（可 RedLock）。</li><li>ZooKeeper：临时顺序节点 + watch，CP 强一致、自动释放，性能低于 Redis。</li><li>数据库：唯一索引/悲观锁，性能最差、易单点。</li></ul><h2 id="链路追踪-★★☆" tabindex="-1">链路追踪 ★★☆ <a class="header-anchor" href="#链路追踪-★★☆" aria-label="Permalink to &quot;链路追踪 ★★☆&quot;">​</a></h2><ul><li>思想：一次请求生成全局 traceId，各服务记录 span 与耗时；常用实现 SkyWalking、Zipkin、Jaeger；组件跨服务透传 traceId 定位慢/失败环节。</li></ul>',20)]))}const b=e(r,[["render",o]]);export{P as __pageData,b as default};
